with unpacked as (select id, effective_from, currency, tier_prices, discounts, slice(tier_limits, 1, 2) as first_two_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers) select date_trunc('week', effective_from) as week_start, sort_array(collect_set(currency)) as currency_list, count(*) filter (where currency = 'USD') as usd_rows from unpacked group by date_trunc('week', effective_from) order by usd_rows desc nulls first
